export const MAP_BOUNDS = {
  minLon: 48,
  maxLon: 98,
  minLat: 5,
  maxLat: 38,
  width: 1000,
  height: 700
};

export function projectCoordinates(lon: number, lat: number): [number, number] {
  const x = ((lon - 48) / (98 - 48)) * 1000;
  const y = (1 - (lat - 5) / (38 - 5)) * 700;
  return [x, y];
}
